const cn = (...values: Array<string | false | undefined>) => values.filter(Boolean).join(' ');

function Button({ children, variant = 'primary', className, ...props }: { children: ReactNode; variant?: 'primary' | 'secondary' | 'ghost' | 'outline' | 'danger'; className?: string; [key: string]: unknown }) {
  const styles = {
    primary: 'bg-[#075985] text-white hover:bg-[#064d70] shadow-sm',
    secondary: 'bg-[#e3f2f2] text-[#075985] hover:bg-[#d2e9e9]',
    outline: 'border border-[#b9d0d2] bg-white text-[#165568] hover:bg-[#f1f8f7]',
    ghost: 'text-[#38616b] hover:bg-[#e9f2f2]',
    danger: 'bg-[#fff0ee] text-[#ac3429] hover:bg-[#ffe5e2]',
  };
  return <button className={cn('focus-ring inline-flex min-h-10 items-center justify-center gap-2 rounded-lg px-4 py-2 text-sm font-semibold transition-colors', styles[variant], className)} {...props}>{children}</button>;
}

function Badge({ children, tone = 'gray' }: { children: ReactNode; tone?: 'blue' | 'green' | 'yellow' | 'red' | 'gray' | 'teal' }) {
  const styles = { blue: 'bg-[#e6f2fb] text-[#075985]', green: 'bg-[#e5f6ee] text-[#18764a]', yellow: 'bg-[#fff5d9] text-[#976d04]', red: 'bg-[#fff0ee] text-[#ac3429]', gray: 'bg-[#edf2f2] text-[#5e7074]', teal: 'bg-[#dff3ef] text-[#116a68]' };
  return <span className={cn('inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-bold tracking-wide', styles[tone])}>{children}</span>;
}

