function ParcelPanel({ parcel, onClose }: { parcel: Parcel; onClose: () => void }) {
  return <aside className="animate-rise rounded-2xl border border-[#c7dddd] bg-white p-5 shadow-soft" data-testid={`panel-parcel-${parcel.ulpin}`}>
    <div className="mb-4 flex items-start justify-between gap-3"><div><div className="mb-1 text-[10px] font-bold uppercase tracking-[.16em] text-[#27807b]">Parcel record</div><h2 className="font-display text-lg font-bold text-[#143e54]">{parcel.owner}</h2><p className="mt-1 text-xs text-[#688087]">{parcel.place} · {parcel.survey}</p></div><button data-testid="button-close-parcel" onClick={onClose} className="focus-ring rounded-md p-1 text-[#789094] hover:bg-[#eef5f3]"><X size={18} /></button></div>
    <div className="mb-4 flex flex-wrap gap-2"><Badge tone={parcel.verified === 'Verified' ? 'green' : 'yellow'}><ShieldCheck size={12} /> {parcel.verified}</Badge><Badge tone="teal">{parcel.ulpin}</Badge></div>
    <div className="grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-[#e1eceb] bg-[#e1eceb]">{[['Area', parcel.area], ['Ownership', parcel.verified], ['Encumbrance', parcel.encumbrance], ['Zoning', parcel.zoning], ['Tax status', parcel.tax], ['Record source', 'State registry']].map(([label, value]) => <div key={label} className="bg-white p-3"><div className="text-[10px] font-bold uppercase tracking-wide text-[#789094]">{label}</div><div className="mt-1 text-xs font-semibold leading-4 text-[#355a64]" data-testid={`text-parcel-${label.toLowerCase().replace(' ', '-')}`}>{value}</div></div>)}</div>
    <div className="mt-4 grid gap-2"><Button data-testid="button-download-ror" variant="secondary"><FileText size={16} /> View Record of Rights</Button><Button data-testid="button-start-service" variant="outline"><ArrowRight size={16} /> Start a service request</Button></div>
  </aside>;
}

function Home() {
  const [query, setQuery] = useState('');
  const [selected, setSelected] = useState<Parcel | null>(null);
  const [toggles, setTogglesState] = useState({ base: true, essential: true, use: false });
  const matches = useMemo(() => query.trim() ? parcels.filter(p => Object.values(p).join(' ').toLowerCase().includes(query.toLowerCase())) : parcels.slice(0, 2), [query]);
  const setToggles = (key: 'base' | 'essential' | 'use') => setTogglesState(prev => ({ ...prev, [key]: !prev[key] }));
  return <div className="page-shell bg-[#f7fbfa]"><Header /><main>
    <section className="border-b border-[#dbe9e7] bg-[linear-gradient(115deg,#eef8f6_0%,#f8fcfb_54%,#e8f3f8_100%)]"><div className="content-wrap grid gap-8 py-10 md:grid-cols-[1.05fr_.95fr] md:items-center md:py-16"><div className="animate-rise"><div className="mb-4 inline-flex items-center gap-2 rounded-full border border-[#bfe0d8] bg-white/75 px-3 py-1.5 text-xs font-bold text-[#1c716e]"><Globe2 size={14} /> One view of India’s land records</div><h1 className="max-w-xl font-display text-4xl font-bold leading-[1.06] tracking-tight text-[#123f54] sm:text-5xl">Know your land.<br /><span className="text-[#187a78]">Know your rights.</span></h1><p className="mt-5 max-w-lg text-base leading-7 text-[#587479]">Find a parcel, understand its official records and follow every land service request — with clarity.</p><div className="mt-7 flex flex-wrap gap-3"><Link href="/account" data-testid="link-view-account" className="focus-ring inline-flex min-h-11 items-center gap-2 rounded-lg bg-[#075985] px-4 py-2 text-sm font-bold text-white shadow-sm hover:bg-[#064d70]">Go to my account <ArrowRight size={16} /></Link><Link href="/admin" data-testid="link-official-console-hero" className="focus-ring inline-flex min-h-11 items-center gap-2 rounded-lg border border-[#b9d0d2] bg-white px-4 py-2 text-sm font-bold text-[#165568] hover:bg-[#f1f8f7]">Official console <Landmark size={16} /></Link></div></div><div className="relative rounded-2xl border border-[#c4deda] bg-white/70 p-3 shadow-[0_15px_45px_rgba(47,99,104,.12)]"><div className="absolute -right-3 -top-3 rounded-lg bg-[#fef9e5] px-3 py-2 text-[11px] font-bold text-[#80630c] shadow-sm">Prototype · illustrative records</div><MapSurface selected={selected} onSelect={setSelected} toggles={toggles} setToggles={setToggles} /></div></div></section>
    <section className="content-wrap py-10"><SectionHeading eyebrow="Parcel explorer" title="Search the public land map" body="Search by ULPIN, owner name, survey number or locality. Select a result to inspect the record and available services." action={<div className="hidden items-center gap-2 md:flex"><SourceBadge label="Registry" /><SourceBadge label="Tax" /></div>} /><SearchBar value={query} onChange={(value) => { setQuery(value); setSelected(null); }} /><div className="mt-6 grid gap-5 lg:grid-cols-[1fr_340px]"><div><div className="mb-3 flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.14em] text-[#71898d]">{query ? `${matches.length} matching records` : 'Suggested records'}</p><button data-testid="button-filter-search" className="focus-ring inline-flex items-center gap-1 text-xs font-bold text-[#217777]"><Filter size={14} /> Filters</button></div><div className="grid gap-3">{matches.map(parcel => <button data-testid={`card-parcel-${parcel.ulpin}`} key={parcel.ulpin} onClick={() => setSelected(parcel)} className={cn('focus-ring w-full rounded-xl border bg-white p-4 text-left transition hover:border-[#79b7b2] hover:shadow-md', selected?.ulpin === parcel.ulpin ? 'border-[#318e89] ring-2 ring-[#d8eeea]' : 'border-[#d9e7e5]')}><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div className="flex gap-3"><span className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#e6f2f3] text-[#157170]"><MapPin size={17} /></span><div><div className="flex flex-wrap items-center gap-2"><h3 className="text-sm font-bold text-[#234d5a]">{parcel.owner}</h3><Badge tone={parcel.verified === 'Verified' ? 'green' : 'yellow'}>{parcel.verified}</Badge></div><p className="mt-1 text-xs text-[#70868a]">{parcel.place} · {parcel.survey}</p></div></div><div className="flex items-center justify-between gap-5 sm:block sm:text-right"><div className="text-sm font-bold text-[#284e58]">{parcel.area}</div><div className="mt-1 text-[11px] text-[#7b9093]">{parcel.ulpin}</div></div></div></button>)}</div>{matches.length === 0 && <div className="rounded-xl border border-dashed border-[#bed4d2] bg-white p-8 text-center"><Search className="mx-auto mb-2 text-[#7aa5a3]" /><p className="text-sm font-semibold text-[#355e64]">No matching parcels</p><p className="mt-1 text-xs text-[#789094]">Try an owner name, ULPIN or locality.</p></div>}</div>{selected ? <ParcelPanel parcel={selected} onClose={() => setSelected(null)} /> : <div className="rounded-2xl border border-[#d9e7e5] bg-[#fbfdfc] p-5"><div className="mb-4 flex h-10 w-10 items-center justify-center rounded-xl bg-[#e5f2ef] text-[#247c77]"><LockKeyhole size={19} /></div><h2 className="font-display text-lg font-bold text-[#234d5a]">Public by design</h2><p className="mt-2 text-sm leading-6 text-[#70868a]">Official sources stay connected while sensitive personal information stays protected. Select a parcel to view what is publicly available.</p><div className="mt-5 grid gap-3 border-t border-[#e2eceb] pt-4"><div className="flex items-center gap-2 text-xs text-[#5d777b]"><CheckCircle2 size={15} className="text-[#258b69]" /> Registry records connected</div><div className="flex items-center gap-2 text-xs text-[#5d777b]"><CheckCircle2 size={15} className="text-[#258b69]" /> Tax status refreshed daily</div></div></div>}</div></section>
    <section className="border-t border-[#dbe9e7] bg-white"><div className="content-wrap grid gap-6 py-10 sm:grid-cols-3"><div><div className="mb-3 text-[#167976]"><Fingerprint /></div><h3 className="font-display font-bold text-[#234d5a]">One parcel identity</h3><p className="mt-1 text-sm leading-6 text-[#71878b]">Every property gets a consistent ULPIN across departments.</p></div><div><div className="mb-3 text-[#167976]"><ClipboardCheck /></div><h3 className="font-display font-bold text-[#234d5a]">Track the full journey</h3><p className="mt-1 text-sm leading-6 text-[#71878b]">See what is happening to your request and who acts next.</p></div><div><div className="mb-3 text-[#167976]"><ShieldCheck /></div><h3 className="font-display font-bold text-[#234d5a]">Built for trust</h3><p className="mt-1 text-sm leading-6 text-[#71878b]">Clear sources, timestamps and review states for every record.</p></div></div></section>
  </main><Footer /></div>;
}

function Timeline({ step }: { step: number }) {
  const items = ['Request submitted', 'Department review', 'Decision recorded', 'Certificate available'];
  return <div className="relative grid gap-4 sm:grid-cols-4">{items.map((item, index) => <div key={item} className="relative flex items-start gap-3 sm:block sm:text-center">{index < items.length - 1 && <div className={cn('absolute left-[13px] top-7 h-[calc(100%+4px)] w-px sm:left-1/2 sm:top-4 sm:h-px sm:w-full', index < step - 1 ? 'bg-[#26936d]' : 'bg-[#d5e3e1]')} />}{<span className={cn('relative z-10 flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-xs font-bold sm:mx-auto', index < step ? 'bg-[#26936d] text-white' : 'bg-[#e9f0ef] text-[#789094]')}>{index < step ? <Check size={14} /> : index + 1}</span>}<div className="pt-1 sm:mt-2 sm:pt-0"><div className={cn('text-xs font-bold', index < step ? 'text-[#35696b]' : 'text-[#809397]')}>{item}</div>{index === step - 1 && <div className="mt-1 text-[10px] text-[#7b9194]">Current stage</div>}</div></div>)}</div>;
}

function AccountPage() {
  const [activeService, setActiveService] = useState<string | null>(null);
  const [toast, setToast] = useState('');
  const submitService = (kind: string) => { setActiveService(kind); setToast(`${kind} request started. You can track it below.`); setTimeout(() => setToast(''), 3500); };
  return <div className="page-shell bg-[#f7fbfa]"><Header /><main className="content-wrap py-8 sm:py-11"><div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mb-2 flex items-center gap-2 text-xs font-bold text-[#247b78]"><UserRound size={15} /> CITIZEN ACCOUNT · DEMO</div><h1 className="font-display text-3xl font-bold tracking-tight text-[#143e54]">Good morning, Ananya</h1><p className="mt-2 text-sm text-[#6b8286]">Your properties, services and official updates in one place.</p></div><div className="flex gap-2"><SourceBadge label="Registry" /><SourceBadge label="Tax" /></div></div>{toast && <div data-testid="status-service-toast" className="mb-5 flex items-center gap-2 rounded-lg border border-[#b9dfcc] bg-[#effaf3] px-4 py-3 text-sm font-semibold text-[#26734d]"><CheckCircle2 size={17} /> {toast}</div>}
    <section className="mb-8"><SectionHeading eyebrow="My properties" title="Properties linked to you" body="These records are connected to your verified citizen profile." /><div className="grid gap-4 lg:grid-cols-2">{parcels.slice(0, 2).map((parcel, i) => <div key={parcel.ulpin} data-testid={`card-owned-property-${i}`} className="overflow-hidden rounded-2xl border border-[#d5e5e2] bg-white shadow-sm"><div className="grid sm:grid-cols-[.85fr_1.15fr]"><div className="relative min-h-[180px] overflow-hidden bg-[#dcece7]"><div className="map-contour absolute inset-0" /><div className="map-parcel left-[27%] top-[26%] h-24 w-36" /><div className="absolute bottom-3 left-3 rounded-md bg-white/90 px-2 py-1 text-[10px] font-bold text-[#3e6c70]">Property {i + 1} · map view</div></div><div className="p-5"><div className="flex items-start justify-between gap-3"><div><h3 className="font-display font-bold text-[#234d5a]">{parcel.place}</h3><p className="mt-1 text-xs text-[#70868a]">{parcel.survey} · {parcel.area}</p></div><Badge tone="green"><ShieldCheck size={12} /> Verified</Badge></div><div className="mt-4 grid grid-cols-2 gap-3 text-xs"><div><div className="text-[#819296]">ULPIN</div><div className="mt-1 font-bold text-[#3b6068]">{parcel.ulpin}</div></div><div><div className="text-[#819296]">Tax status</div><div data-testid={`status-property-tax-${i}`} className="mt-1 font-bold text-[#25825b]">{parcel.tax}</div></div></div><button data-testid={`button-view-property-${i}`} onClick={() => submitService('Property record')} className="focus-ring mt-5 inline-flex items-center gap-1 text-xs font-bold text-[#17716f]">View full property record <ArrowRight size={14} /></button></div></div></div>)}</div></section>
    <section className="mb-8"><SectionHeading eyebrow="Start a service" title="What do you need to do?" body="Choose a service to prepare an official request." /><div className="grid gap-3 sm:grid-cols-3">{([['Title transfer', 'Update ownership after a sale, inheritance or gift', FileCheck2], ['Building permission', 'Check permissions before you build or renovate', Building2], ['Ownership dispute', 'Raise a correction or dispute on a record', CircleHelp]] as const).map(([title, body, Icon]) => <button data-testid={`button-service-${String(title).toLowerCase().replace(' ', '-')}`} key={String(title)} onClick={() => submitService(String(title))} className="focus-ring group rounded-xl border border-[#d5e5e2] bg-white p-5 text-left transition hover:-translate-y-0.5 hover:border-[#78b4ae] hover:shadow-md"><span className="mb-4 flex h-10 w-10 items-center justify-center rounded-lg bg-[#e6f2f1] text-[#167675]"><Icon size={19} /></span><span className="block font-display text-sm font-bold text-[#315b65]">{title}</span><span className="mt-1 block text-xs leading-5 text-[#789094]">{body}</span><span className="mt-4 flex items-center gap-1 text-xs font-bold text-[#197271]">Start request <ArrowRight size={13} className="transition-transform group-hover:translate-x-1" /></span></button>)}</div></section>
    <section><SectionHeading eyebrow="Activity" title="Your service requests" body="Follow progress from submission to certificate." action={<button data-testid="button-filter-requests" className="focus-ring inline-flex items-center gap-2 text-xs font-bold text-[#207471]"><Filter size={15} /> Filter requests</button>} /><div className="grid gap-4">{serviceRequests.map(request => <article key={request.id} data-testid={`card-request-${request.id}`} className="rounded-2xl border border-[#d5e5e2] bg-white p-5 shadow-sm"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><div className="flex flex-wrap items-center gap-2"><h3 className="font-display text-sm font-bold text-[#234d5a]">{request.kind}</h3><Badge tone={request.tone as 'blue' | 'green' | 'yellow'}>{request.status}</Badge></div><p data-testid={`text-request-id-${request.id}`} className="mt-1 text-xs text-[#7c9194]">{request.id} · Submitted {request.date}</p></div><button data-testid={`button-open-request-${request.id}`} onClick={() => setToast(`Opening ${request.id} details`)} className="focus-ring inline-flex items-center gap-1 text-xs font-bold text-[#207471]">View details <ChevronRight size={14} /></button></div><div className="mt-5 border-t border-[#edf2f0] pt-5"><Timeline step={request.step} /></div></article>)}</div></section>
  </main><Footer /></div>;
}

function AdminShell({ children }: { children: ReactNode }) {
  const [collapsed, setCollapsed] = useState(false);
  return <div className="page-shell bg-[#f5f9f8]"><Header admin /><div className="flex"><aside className={cn('hidden min-h-[calc(100dvh-68px)] shrink-0 border-r border-[#d2e1df] bg-[#133c50] p-4 text-[#dcecee] transition-all lg:block', collapsed ? 'w-[80px]' : 'w-[254px]')}><div className={cn('mb-7 flex items-center', collapsed ? 'justify-center' : 'justify-between')}><span className={cn('text-[10px] font-bold uppercase tracking-[.17em] text-[#75bebc]', collapsed && 'hidden')}>Workspace</span><button data-testid="button-collapse-admin-nav" onClick={() => setCollapsed(!collapsed)} className="focus-ring rounded-md p-2 text-[#b4d7d6] hover:bg-[#214e60]">{collapsed ? <PanelLeftOpen size={17} /> : <PanelLeftClose size={17} />}</button></div><nav className="grid gap-1">{([['Overview', '/admin', BarChart3], ['Workflow inbox', '/admin/workflows', Activity], ['OCR digitization', '/admin/ocr', ScanIcon], ['Record quality', '/admin', Tags]] as const).map(([label, href, Icon]) => <Link key={String(label)} href={String(href)} data-testid={`link-admin-nav-${String(label).toLowerCase().replace(' ', '-')}`} className={cn('flex items-center gap-3 rounded-lg px-3 py-3 text-sm font-semibold transition', collapsed && 'justify-center px-0', locationPath() === href ? 'bg-[#236270] text-white' : 'text-[#b7d1d2] hover:bg-[#1f4d5d] hover:text-white')}><Icon size={18} /><span className={cn(collapsed && 'hidden')}>{label}</span></Link>)}</nav><div className={cn('mt-auto pt-14', collapsed && 'hidden')}><div className="rounded-xl border border-[#315c68] bg-[#1a485a] p-3"><div className="flex items-center gap-2 text-xs font-bold text-[#dcefee]"><Sparkles size={14} className="text-[#8bd1c5]" /> Prototype workspace</div><p className="mt-2 text-[11px] leading-5 text-[#a8c8ca]">Demo records help teams test a transparent land workflow.</p></div></div></aside><div className="min-w-0 flex-1">{children}</div></div></div>;
}

function locationPath() { return typeof window !== 'undefined' ? window.location.pathname : '/admin'; }
function ScanIcon(props: { size?: number }) { return <CloudUpload {...props} />; }

function AdminOverview() {
  const [notice, setNotice] = useState('');
  return <AdminShell><main className="content-wrap py-8 sm:py-10"><div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mb-2 flex items-center gap-2 text-xs font-bold text-[#247b78]"><Landmark size={15} /> OFFICIAL CONSOLE · DEMO</div><h1 className="font-display text-3xl font-bold tracking-tight text-[#143e54]">State land records overview</h1><p className="mt-2 text-sm text-[#6b8286]">Wednesday, 19 February 2025 · Karnataka pilot workspace</p></div><div className="flex items-center gap-2"><Badge tone="green"><span className="h-1.5 w-1.5 rounded-full bg-[#268b68]" /> Systems operational</Badge><button data-testid="button-admin-notifications" onClick={() => setNotice('No new critical alerts')} className="focus-ring rounded-lg border border-[#cadfdd] bg-white p-2 text-[#56777c]"><Bell size={17} /></button></div></div>{notice && <div data-testid="status-admin-notice" className="mb-5 rounded-lg border border-[#c4ddd9] bg-white px-4 py-3 text-sm font-semibold text-[#3b6a70]">{notice}</div>}<div className="mb-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{([['Transactions today', '1,284', '+12.4%', BarChart3, 'blue'], ['Pending approvals', '64', '8 due today', ClipboardCheck, 'yellow'], ['Records digitized', '82.6%', '+3.1% this month', FileCheck2, 'green'], ['Satellite changes', '18', '4 high priority', Globe2, 'red']] as const).map(([label, value, note, Icon, tone], index) => <div data-testid={`card-admin-stat-${index}`} key={String(label)} className="rounded-2xl border border-[#d4e4e2] bg-white p-5 shadow-sm"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-wide text-[#789094]">{label}</p><p data-testid={`text-admin-stat-${index}`} className="mt-3 font-display text-3xl font-bold text-[#153f55]">{value}</p><p className={cn('mt-2 text-xs font-semibold', tone === 'green' ? 'text-[#25825b]' : tone === 'red' ? 'text-[#b64539]' : tone === 'yellow' ? 'text-[#98740c]' : 'text-[#217879]')}>{note}</p></div><span className={cn('flex h-10 w-10 items-center justify-center rounded-lg', tone === 'green' ? 'bg-[#e5f6ee] text-[#25825b]' : tone === 'red' ? 'bg-[#fff0ee] text-[#b64539]' : tone === 'yellow' ? 'bg-[#fff6dc] text-[#98740c]' : 'bg-[#e6f2fb] text-[#217879]')}><Icon size={19} /></span></div></div>)}</div><section data-testid="card-ai-ml-insight-alert" className="mb-8 flex flex-col gap-4 rounded-2xl border border-[#e6c879] bg-[#fff8e3] p-5 shadow-sm sm:flex-row sm:items-center sm:justify-between"><div className="flex items-start gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-[#fbe6a9] text-[#946b09]"><AlertTriangle size={20} /></span><div><div className="mb-1 flex flex-wrap items-center gap-2"><span className="text-[11px] font-bold uppercase tracking-[.16em] text-[#946b09]">AI/ML insights · urgent review</span><Badge tone="yellow">Illustrative alert</Badge></div><p data-testid="text-ai-ml-insight-alert" className="text-sm font-bold leading-6 text-[#654f16]">Satellite Change Detection Alert: 3 unauthorized constructions detected on ULPIN #12345</p><p className="mt-1 text-xs text-[#8b7330]">Automated satellite analysis is a decision-support signal and requires official verification.</p></div></div><Link href="/admin/workflows" data-testid="link-review-ai-ml-alert" className="focus-ring inline-flex shrink-0 items-center justify-center gap-2 rounded-lg bg-[#9b7209] px-4 py-2.5 text-sm font-bold text-white hover:bg-[#805d06]">Review alert <ArrowRight size={15} /></Link></section><div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><section className="rounded-2xl border border-[#d4e4e2] bg-white p-5 shadow-sm"><div className="mb-5 flex items-start justify-between gap-3"><div><div className="text-[11px] font-bold uppercase tracking-[.16em] text-[#27807b]">Service volume</div><h2 className="mt-1 font-display text-lg font-bold text-[#234d5a]">Requests across departments</h2></div><select data-testid="select-dashboard-range" className="focus-ring rounded-lg border border-[#d7e4e2] bg-white px-2 py-2 text-xs text-[#5d777b]"><option>Last 30 days</option><option>Last 7 days</option></select></div><div className="flex h-52 items-end gap-2 border-b border-l border-[#dfebea] px-3 pb-0 pt-6">{[42,55,48,68,62,76,72,81,67,92,79,88,95,87,100,89,97,78].map((height, i) => <div key={i} className="group flex h-full flex-1 flex-col justify-end gap-2"><div className="rounded-t-sm bg-[#3e9d95] transition-opacity group-hover:opacity-70" style={{ height: `${height}%` }} /><div className="text-center text-[9px] text-[#98a9aa]">{i % 3 === 0 ? `${i + 1} Feb` : ''}</div></div>)}</div><div className="mt-4 flex flex-wrap gap-4 text-xs text-[#71878b]"><span className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-sm bg-[#3e9d95]" /> All requests</span><span className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-sm bg-[#f2c35e]" /> Approvals due</span></div></section><section className="rounded-2xl border border-[#d4e4e2] bg-white p-5 shadow-sm"><div className="mb-5 flex items-start justify-between"><div><div className="text-[11px] font-bold uppercase tracking-[.16em] text-[#27807b]">Action queue</div><h2 className="mt-1 font-display text-lg font-bold text-[#234d5a]">Needs attention</h2></div><Badge tone="yellow">8 open</Badge></div><div className="grid gap-3">{([['Workflow approvals', '8 requests due today', 'yellow', '/admin/workflows'], ['OCR confidence review', '12 scans below 90%', 'blue', '/admin/ocr'], ['Satellite change alerts', '4 high priority parcels', 'red', '/admin']] as const).map(([title, sub, tone, href]) => <Link href={href} key={title} data-testid={`link-action-${title.toLowerCase().replace(' ', '-')}`} className="flex items-center justify-between rounded-lg border border-[#e2eceb] p-3 hover:border-[#8abcb6]"><div className="flex items-center gap-3"><span className={cn('h-2.5 w-2.5 rounded-full', tone === 'yellow' ? 'bg-[#e3b33f]' : tone === 'red' ? 'bg-[#d45a4d]' : 'bg-[#3e9dbe]')} /><div><div className="text-sm font-bold text-[#3e6068]">{title}</div><div className="mt-0.5 text-xs text-[#849699]">{sub}</div></div></div><ChevronRight size={16} className="text-[#8aa0a2]" /></Link>)}</div></section></div><section className="mt-6 rounded-2xl border border-[#d4e4e2] bg-white p-5 shadow-sm"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><div className="text-[11px] font-bold uppercase tracking-[.16em] text-[#27807b]">Live monitor</div><h2 className="mt-1 font-display text-lg font-bold text-[#234d5a]">Recent approvals</h2></div><button data-testid="button-export-approvals" onClick={() => setNotice('Approval report prepared for download')} className="focus-ring inline-flex items-center gap-2 text-xs font-bold text-[#207471]"><FileText size={15} /> Export report</button></div><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="border-b border-[#e3eceb] text-[10px] font-bold uppercase tracking-wide text-[#829497]"><tr><th className="pb-3">Request</th><th className="pb-3">Department</th><th className="pb-3">Decision maker</th><th className="pb-3">Updated</th><th className="pb-3">Status</th></tr></thead><tbody className="divide-y divide-[#edf2f1]">{[['LS-2025-0381', 'Town Planning', 'R. Narayanan', '14 min ago'], ['LS-2025-0366', 'Revenue Department', 'P. Sharma', '42 min ago'], ['LS-2025-0359', 'Survey & Land Records', 'K. Hegde', '1 hr ago']].map(row => <tr key={row[0]} data-testid={`row-approval-${row[0]}`}><td className="py-4 font-bold text-[#3b6068]">{row[0]}</td><td className="py-4 text-[#71878b]">{row[1]}</td><td className="py-4 text-[#71878b]">{row[2]}</td><td className="py-4 text-[#71878b]">{row[3]}</td><td className="py-4"><Badge tone="green">Approved</Badge></td></tr>)}</tbody></table></div></section></main></AdminShell>;
}

export async function processOCRData(file: File): Promise<{ owner: string; survey: string; area: string; ulpin: string }> {
  await new Promise(resolve => setTimeout(resolve, 2000));
  return { owner: file.name.toLowerCase().includes('patil') ? 'Suresh Patil' : 'Ananya Rao', survey: '124/3A', area: '1,240 sq ft', ulpin: 'IN-KA-03-245-1890-0123' };
}

function OCRPage() {
  const [file, setFile] = useState<File | null>(null);
  const [dragging, setDragging] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [result, setResult] = useState<{ owner: string; survey: string; area: string; ulpin: string } | null>(null);
  const [saved, setSaved] = useState(false);
  const loadFile = (next: File | undefined) => { if (next) { setFile(next); setResult(null); setSaved(false); } };
  const onDrop = (event: DragEvent<HTMLDivElement>) => { event.preventDefault(); setDragging(false); loadFile(event.dataTransfer.files[0]); };
  const extract = async () => { if (!file) return; setProcessing(true); setSaved(false); setResult(await processOCRData(file)); setProcessing(false); };
  return <AdminShell><main className="content-wrap py-8 sm:py-10"><SectionHeading eyebrow="Record digitization" title="OCR digitization" body="Turn scanned legacy land records into structured data for review. Every extracted value remains editable until an official saves it." action={<Badge tone="blue"><FileCheck2 size={13} /> Human review required</Badge>} /><div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><section><div onDragOver={(e) => { e.preventDefault(); setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={onDrop} className={cn('rounded-2xl border-2 border-dashed bg-white p-7 text-center transition', dragging ? 'border-[#188784] bg-[#f1faf8]' : 'border-[#bfd6d3]')}><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[#e3f2f0] text-[#187b78]"><CloudUpload size={26} /></div><h2 className="mt-4 font-display text-lg font-bold text-[#234d5a]">Drop a land record here</h2><p className="mx-auto mt-2 max-w-xs text-sm leading-6 text-[#799094]">Upload a JPG, PNG or PDF scan. Use a clear scan for higher extraction confidence.</p><label data-testid="label-ocr-file-picker" className="focus-ring mt-5 inline-flex min-h-10 cursor-pointer items-center gap-2 rounded-lg border border-[#b9d0d2] bg-white px-4 py-2 text-sm font-bold text-[#165568] hover:bg-[#f1f8f7]"><Upload size={16} /> Choose file<input data-testid="input-ocr-file" type="file" accept=".jpg,.jpeg,.png,.pdf" className="sr-only" onChange={(e: ChangeEvent<HTMLInputElement>) => loadFile(e.target.files?.[0])} /></label>{file && <div data-testid="text-ocr-selected-file" className="mt-5 flex items-center justify-between rounded-lg border border-[#d9e7e5] bg-[#f8fbfa] p-3 text-left"><div className="flex min-w-0 items-center gap-3"><FileText className="shrink-0 text-[#26827e]" size={20} /><div className="min-w-0"><div className="truncate text-sm font-bold text-[#3b6068]">{file.name}</div><div className="text-[11px] text-[#839598]">{Math.max(1, Math.round(file.size / 1024))} KB · ready to process</div></div></div><button data-testid="button-remove-ocr-file" onClick={() => setFile(null)} className="focus-ring rounded p-1 text-[#789094] hover:bg-[#eaf2f0]"><X size={16} /></button></div>}{file && <Button data-testid="button-extract-ocr" onClick={extract} className="mt-5 w-full" disabled={processing}>{processing ? <><Activity size={16} className="animate-pulse" /> Extracting record data…</> : <><Sparkles size={16} /> Extract data</>}</Button>}</div><div className="mt-5 rounded-xl border border-[#d9e7e5] bg-[#f8fbfa] p-4"><div className="flex gap-3"><CircleHelp size={17} className="mt-0.5 shrink-0 text-[#498187]" /><div><h3 className="text-sm font-bold text-[#3e6068]">What happens next?</h3><p className="mt-1 text-xs leading-5 text-[#789094]">Land Stack identifies common fields, shows confidence for review and never publishes extracted data without an official save.</p></div></div></div></section><section className="rounded-2xl border border-[#d4e4e2] bg-white p-5 shadow-sm"><div className="mb-5 flex items-center justify-between gap-3"><div><div className="text-[11px] font-bold uppercase tracking-[.16em] text-[#27807b]">Extraction workspace</div><h2 className="mt-1 font-display text-lg font-bold text-[#234d5a]">Review extracted fields</h2></div>{result && <Badge tone="green"><CheckCircle2 size={13} /> 94% confidence</Badge>}</div>{processing ? <div data-testid="ocr-loading-skeleton" className="grid gap-5">{[1,2,3,4].map(i => <div key={i}><div className="skeleton mb-2 h-3 w-28 rounded" /><div className="skeleton h-11 w-full rounded-lg" /></div>)}</div> : result ? <div className="grid gap-4">{([['owner', 'Owner name'], ['survey', 'Survey number'], ['area', 'Land area'], ['ulpin', 'ULPIN']] as const).map(([key, label]) => <label key={key} className="grid gap-2"><span className="text-xs font-bold text-[#587479]">{label}</span><input data-testid={`input-ocr-${key}`} value={result[key]} onChange={(e) => setResult({ ...result, [key]: e.target.value })} className="focus-ring rounded-lg border border-[#cbdedc] bg-[#fbfdfc] px-3 py-3 text-sm font-semibold text-[#315b65] outline-none focus:border-[#3a9992]" /></label>)}<div className="mt-2 flex flex-wrap gap-3 border-t border-[#e6eeed] pt-5"><Button data-testid="button-save-ocr" onClick={() => setSaved(true)}><Check size={16} /> Save to review queue</Button><Button data-testid="button-reset-ocr" variant="outline" onClick={() => setResult(null)}>Discard extraction</Button></div>{saved && <div data-testid="status-ocr-saved" className="flex items-center gap-2 rounded-lg border border-[#b9dfcc] bg-[#effaf3] px-3 py-3 text-sm font-semibold text-[#26734d]"><CheckCircle2 size={16} /> Saved to the digitization review queue.</div>}</div> : <div data-testid="ocr-empty-state" className="flex min-h-[340px] flex-col items-center justify-center rounded-xl border border-dashed border-[#d5e5e2] bg-[#fbfdfc] px-8 text-center"><FileText className="text-[#89aaa9]" size={32} /><h3 className="mt-4 font-display font-bold text-[#3b6068]">No record selected</h3><p className="mt-1 max-w-xs text-sm leading-6 text-[#819598]">Choose a scanned file to preview structured fields here.</p></div>}</section></div></main></AdminShell>;
}

function WorkflowsPage() {
  const [selected, setSelected] = useState<typeof workflowRows[number] | null>(null);
  const [status, setStatus] = useState('');
  const act = (action: string) => { setStatus(`${action} recorded for ${selected?.id}`); setSelected(null); };
  return <AdminShell><main className="content-wrap py-8 sm:py-10"><SectionHeading eyebrow="Inter-department coordination" title="Workflow inbox" body="Review requests handed between departments and record the next action with an auditable trail." action={<Button data-testid="button-refresh-workflows" variant="outline" onClick={() => setStatus('Inbox refreshed just now')}><Activity size={15} /> Refresh inbox</Button>} />{status && <div data-testid="status-workflow-action" className="mb-5 flex items-center gap-2 rounded-lg border border-[#c4ddd9] bg-white px-4 py-3 text-sm font-semibold text-[#3b6a70]"><CheckCircle2 size={16} /> {status}</div>}<div className="mb-5 grid gap-3 sm:grid-cols-3">{[['Needs review', '2', 'yellow'], ['In progress', '1', 'blue'], ['Waiting on applicant', '1', 'gray']].map(([label, value, tone]) => <button data-testid={`button-workflow-filter-${label.toLowerCase().replace(' ', '-')}`} key={label} className="focus-ring flex items-center justify-between rounded-xl border border-[#d4e4e2] bg-white p-4 text-left shadow-sm hover:border-[#8abcb6]"><span className="text-xs font-bold text-[#6c8589]">{label}</span><span className={cn('font-display text-xl font-bold', tone === 'yellow' ? 'text-[#a47b0c]' : tone === 'blue' ? 'text-[#247898]' : 'text-[#6b8286]')}>{value}</span></button>)}</div><section className="overflow-hidden rounded-2xl border border-[#d4e4e2] bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e4edeb] p-5"><div><h2 className="font-display text-lg font-bold text-[#234d5a]">Requests requiring coordination</h2><p className="mt-1 text-xs text-[#7e9396]">All times shown in IST · prototype queue</p></div><div className="flex gap-2"><button data-testid="button-workflow-filter" className="focus-ring rounded-lg border border-[#d4e4e2] p-2 text-[#5d7b7f]"><Filter size={16} /></button><button data-testid="button-workflow-more" className="focus-ring rounded-lg border border-[#d4e4e2] p-2 text-[#5d7b7f]"><MoreHorizontal size={16} /></button></div></div><div className="divide-y divide-[#e7efed]">{workflowRows.map(row => <div data-testid={`row-workflow-${row.id}`} key={row.id} className="flex flex-col gap-4 p-5 transition hover:bg-[#fbfdfc] lg:flex-row lg:items-center"><div className="flex min-w-0 flex-1 items-start gap-3"><span className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#e8f2f1] text-[#277c79]"><Stamp size={17} /></span><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="font-display text-sm font-bold text-[#315b65]">{row.id}</span><Badge tone={row.tone as 'yellow' | 'blue' | 'gray'}>{row.status}</Badge></div><div className="mt-1 text-sm font-semibold text-[#4d6d73]">{row.request}</div><div className="mt-1 flex flex-wrap gap-x-4 gap-y-1 text-xs text-[#849699]"><span>{row.dept}</span><span>Due {row.due}</span></div></div></div><Button data-testid={`button-review-workflow-${row.id}`} variant={row.status === 'Needs review' ? 'primary' : 'outline'} onClick={() => setSelected(row)} className="w-full lg:w-auto">{row.status === 'Needs review' ? 'Review request' : 'Open request'} <ArrowRight size={14} /></Button></div>)}</div></section>{selected && <div className="fixed inset-0 z-50 flex items-end justify-center bg-[#123c51]/30 p-0 sm:items-center sm:p-4"><div role="dialog" aria-modal="true" className="animate-rise w-full max-w-lg rounded-t-2xl border border-[#d3e4e1] bg-white p-6 shadow-lg sm:rounded-2xl"><div className="flex items-start justify-between"><div><div className="text-[11px] font-bold uppercase tracking-[.16em] text-[#27807b]">Review action</div><h2 className="mt-1 font-display text-xl font-bold text-[#234d5a]">{selected.id}</h2></div><button data-testid="button-close-workflow-dialog" onClick={() => setSelected(null)} className="focus-ring rounded p-1 text-[#789094]"><X size={18} /></button></div><div className="mt-5 rounded-xl bg-[#f5faf8] p-4"><p className="text-sm font-bold text-[#3b6068]">{selected.request}</p><p className="mt-2 text-xs leading-5 text-[#789094]">Initiating department: {selected.dept}. Select a next action to keep the request moving.</p></div><div className="mt-5 grid gap-2"><Button data-testid="button-approve-workflow" onClick={() => act('Approval')}><Check size={16} /> Approve and forward</Button><Button data-testid="button-request-workflow-info" variant="secondary" onClick={() => act('Information request')}>Request more information</Button><Button data-testid="button-return-workflow" variant="danger" onClick={() => act('Return for correction')}>Return for correction</Button></div></div></div>}</main></AdminShell>;
}

function Footer() {
  return <footer className="border-t border-[#dbe9e7] bg-[#f3f9f7]"><div className="content-wrap flex flex-col justify-between gap-3 py-6 text-xs text-[#71878b] sm:flex-row sm:items-center"><div className="flex items-center gap-2"><Landmark size={15} className="text-[#197370]" /><span>Land Stack · Public digital land records prototype</span></div><div className="flex gap-4"><span>Data privacy</span><span>Help centre</span><span>Accessibility</span></div></div></footer>;
}

function Router() {
  return <ErrorBoundary resetKey={typeof window !== 'undefined' ? window.location.pathname : '/'}><Switch><Route path="/" component={Home} /><Route path="/account" component={AccountPage} /><Route path="/admin" component={AdminOverview} /><Route path="/admin/ocr" component={OCRPage} /><Route path="/admin/workflows" component={WorkflowsPage} /><Route component={NotFound} /></Switch></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;